        SingleFcn g = gen.getFn();
        SingleFcn p = plain.getFn();
        SingleFcn holding = instanceHolding(g, plain.getParams(), true);
        boolean genInside = declaredBelow(g, null, p, p, true);
        if (holding != null && genInside) return false;
        if (holding != null) return p.getRange().subtypeOf(holding.getRange());
        if (genInside) return g.getRange().subtypeOf(p.getRange());
