cd /home/user/fortress-dispatch && python3 - <<'EOF'
import re,glob,collections
pat=re.compile(r'^\s*(opr\s+)?([^\s\[(]+)\s*\[\\(.*?)\\\]\s*\(', re.M)
res=collections.defaultdict(list)
for f in glob.glob('Library/*.fss')+glob.glob('Library/*.fsi'):
    for i,l in enumerate(open(f,encoding='utf-8',errors='replace')):
        m=pat.match(l)
        if m:
            name=m.group(2); sp=m.group(3)
            # normalise
            parts=[p.strip() for p in re.split(r',(?![^\[]*\\\])',sp)]
            names=tuple(re.split(r'\s+extends\s+|\s',p.replace('nat ','').replace('int ','').replace('bool ','').replace('opr ','').strip())[0] for p in parts)
            res[(f.endswith('.fss'),name,names)].append((sp.strip(), f, i+1))
n=0
for k,v in res.items():
    if not k[0]: continue
    bounds=set(x[0] for x in v)
    if len(bounds)>1:
        n+=1
        print(k[1], k[2]); 
        for x in v: print('   ', x[0], x[1]+':'+str(x[2]))
print(n)
EOF

